class JobSeekerDashboardScreen extends StatefulWidget {
  const JobSeekerDashboardScreen({super.key,required this.service,required this.onBrowseJobs});
  final JobSeekerService service; final VoidCallback onBrowseJobs;
  @override State<JobSeekerDashboardScreen> createState()=>_State();
