  @override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return _Error(message:error!,retry:_load);final d=data!;return RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('Welcome, ${d.fullName.isEmpty?'Job Seeker':d.fullName}',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:6),const Text('Track your progress and discover your next opportunity.',style:TextStyle(color:AppTheme.muted)),const SizedBox(height:18),GridView.count(crossAxisCount:2,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:1.20,children:[_Stat('Applications','${d.totalApplications}',Icons.assignment_rounded),_Stat('Active','${d.activeApplications}',Icons.timelapse_rounded),_Stat('Interviews','${d.interviewApplications}',Icons.event_available_rounded),_Stat('Available jobs','${d.availableJobs}',Icons.work_rounded)]),const SizedBox(height:16),_Card(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Profile strength',style:TextStyle(fontWeight:FontWeight.w800,fontSize:16)),const SizedBox(height:10),LinearProgressIndicator(value:(d.profileCompleteness.clamp(0,100))/100),const SizedBox(height:8),Text('${d.profileCompleteness}% complete • ${d.skillsCount} skills • CV ${d.cvUploaded?'uploaded':'not uploaded'}',style:const TextStyle(color:AppTheme.muted)),const SizedBox(height:8),Text('Average skill match: ${d.averageMatchScore.toStringAsFixed(0)}%',style:const TextStyle(fontWeight:FontWeight.w600))])),if(d.topGapSkills.isNotEmpty)...[const SizedBox(height:16),_Card(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Top skill gaps',style:TextStyle(fontWeight:FontWeight.w800,fontSize:16)),const SizedBox(height:10),Wrap(spacing:8,runSpacing:8,children:d.topGapSkills.map((s)=>Chip(label:Text(s))).toList())]))],const SizedBox(height:16),FilledButton.icon(onPressed:widget.onBrowseJobs,icon:const Icon(Icons.search_rounded),label:const Text('Browse available jobs'))]));}
