class _Stat extends StatelessWidget{const _Stat(this.label,this.value,this.icon);final String label,value;final IconData icon;@override Widget build(BuildContext c)=>_Card(child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.center,children:[Icon(icon,color:AppTheme.violet),const SizedBox(height:8),Text(value,style:const TextStyle(fontWeight:FontWeight.w900,fontSize:22)),const SizedBox(height:4),Flexible(child:Text(label,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(color:AppTheme.muted,fontSize:12,height:1.2)))]));}
